const body = $input.first().json.body;

const record = {
  fullName: body.fullName,
  employeeNumber: body.employeeNumber,
  email: body.email,
  phone: body.phone,
  motivation: body.motivation,
  status: 'pending',
  requestedAt: new Date().toISOString()
};

return [{ json: record }];
